# The overview recipe predates the review style family and contains white
# labels in its base skin. Rebind every overview text role to the active
# palette so light skins remain readable without changing the layout.
STYLE += """
.scene[data-visual-style^="review-"] .review-overview{color:var(--review-ink)!important}
.scene[data-visual-style^="review-"] .review-overview-heading h3{color:var(--review-heading)!important}
.scene[data-visual-style^="review-"] .review-overview-heading p{color:var(--review-muted)!important}
.scene[data-visual-style^="review-"] .review-overview-kicker,.scene[data-visual-style^="review-"] .review-overview-card span,.scene[data-visual-style^="review-"] .review-overview-path-label{color:var(--review-accent)!important}
.scene[data-visual-style^="review-"] .review-overview-card p,.scene[data-visual-style^="review-"] .review-overview-path li,.scene[data-visual-style^="review-"] .review-overview-path li strong,.scene[data-visual-style^="review-"] .review-overview-path li span{color:var(--review-ink)!important}
.scene[data-visual-style^="review-"] .review-overview-card,.scene[data-visual-style^="review-"] .review-overview-path li{background:var(--review-surface)!important;border-color:var(--review-border)!important}
.scene[data-visual-style^="review-"] .review-completion-summary>span,.scene[data-visual-style^="review-"] .review-completion-summary p{color:var(--review-action-ink)!important}
""".strip()

